@tool
extends Node

func run() -> String:
	var base := "C:/Users/Alex/AppData/Roaming/Godot/app_userdata/Ghost Company/logs"
	var logs := ["godot2026-11-03T16.07.33.log", "godot2026-11-03T16.08.30.log", "godot2026-11-03T16.09.04.log", "godot2026-11-03T16.11.40.log", "godot.log"]
	var rep := {}
	var err_total := 0
	var warn_total := 0
	var patterns := {}
	var samples: Array = []
	for lg in logs:
		var p := base + "/" + String(lg)
		if not FileAccess.file_exists(p):
			continue
		var txt := FileAccess.get_file_as_string(p)
		var lines := txt.split("\n")
		var ec := 0
		var wc := 0
		for ln in lines:
			var s := String(ln).strip_edges()
			if s.begins_with("ERROR") or (":ERROR:" in s) or ("ERROR:" in s):
				ec += 1
				err_total += 1
				var pat := s.substr(0, 120)
				patterns[pat] = int(patterns.get(pat, 0)) + 1
			elif s.begins_with("WARNING") or ("WARNING:" in s):
				wc += 1
				warn_total += 1
			if samples.size() < 60 and (("ERROR" in s) or ("WARNING" in s)):
				samples.append(String(lg) + " | " + s.substr(0, 160))
		rep[String(lg)] = {"errors": ec, "warnings": wc, "lines": lines.size()}
	var top: Array = []
	for k in patterns.keys():
		top.append(str(patterns[k]) + "x | " + String(k))
	top.sort()
	# existence checks for the stragglers
	var checks := {}
	checks["new_gltf_decal_line90"] = FileAccess.file_exists("res://assets/gltf/Decals/Decal_Line_90.gltf")
	checks["new_gltf_decal_line90_import"] = FileAccess.file_exists("res://assets/gltf/Decals/Decal_Line_90.gltf.import")
	checks["rmsmartshape_icon0_svg"] = FileAccess.file_exists("res://addons/rmsmartshape/assets/icon_width_handle.svg")
	checks["road_segment_png"] = FileAccess.file_exists("res://addons/road-generator/resources/road_segment.png")
	rep["error_total"] = err_total
	rep["warning_total"] = warn_total
	rep["top_patterns"] = top
	rep["samples"] = samples
	rep["checks"] = checks
	var out := FileAccess.open("res://tools/gc_diag_report2.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "DIAG2 rc=0 err=" + str(err_total) + " warn=" + str(warn_total)
